//! Review findings as tests. Generated by `tools/regressions.py` from oracle
//! output. Do not edit by hand.

#![allow(clippy::unwrap_used)]

use randoc_ast::json::from_json;
use randoc_core::{
    CaptionPosition, CiteMethod, Context, FormatSpec, TopLevelDivision, WriterOptions,
};

fn render(input: &str, format: &str, set: impl FnOnce(&mut WriterOptions)) -> String {
    let doc = from_json(input).unwrap();
    let spec = FormatSpec::parse(format);
    let mut options = WriterOptions::default();
    options.extensions = spec.extensions().unwrap();
    set(&mut options);
    let mut context = Context::pure();
    let text = if spec.name == "beamer" {
        randoc_latex::write_beamer(&doc, &options, &mut context)
    } else {
        randoc_latex::write_latex(&doc, &options, &mut context)
    };
    text.unwrap()
}

#[test]
fn unicode_spaces_and_spanish_ligatures() {
    let input = r###"{"pandoc-api-version": [1, 23, 1, 2], "meta": {}, "blocks": [{"t": "Para", "c": [{"t": "Str", "c": "x\u200by\u00adz\u202fw!`e?`f"}]}]}"###;
    let expected = r###"x\hspace{0pt}y\-z\,w!{\kern0pt}`e?{\kern0pt}`f"###;
    assert_eq!(
        render(input, "latex", |options| {
            let _ = &options;
        }),
        expected
    );
}

