#[test]
fn babel_names_of_five_languages() {
    let input = r###"{"pandoc-api-version": [1, 23, 1, 2], "meta": {}, "blocks": [{"t": "Para", "c": [{"t": "Span", "c": [["", [], [["lang", "as"]]], [{"t": "Str", "c": "x"}]]}, {"t": "Span", "c": [["", [], [["lang", "gu"]]], [{"t": "Str", "c": "x"}]]}, {"t": "Span", "c": [["", [], [["lang", "ie"]]], [{"t": "Str", "c": "x"}]]}, {"t": "Span", "c": [["", [], [["lang", "or"]]], [{"t": "Str", "c": "x"}]]}, {"t": "Span", "c": [["", [], [["lang", "ti"]]], [{"t": "Str", "c": "x"}]]}]}]}"###;
    let expected = r###"\foreignlanguage{assamese}{x}\foreignlanguage{gujarati}{x}\foreignlanguage{interlingua}{x}\foreignlanguage{oriya}{x}\foreignlanguage{ethiopic}{x}"###;
    assert_eq!(
        render(input, "latex", |options| {
            let _ = &options;
        }),
        expected
    );
}
